import { createAction } from '../../utils/reducer/reducer.utils';
import { CATEGORIES_ACTION_TYPE } from './category.types';

export const setCategoriesMapGb = (categories) => {
    return createAction(CATEGORIES_ACTION_TYPE.SET_CATEGORIES_MAP, categories);
};
